pub fn resolveImportsExportsReverse(r: *const ESModule, query: []const u8, match_obj: ExportsMap.Entry) ?ReverseResolution {
            if ((match_obj.data != .map)) {
                return null;
            }
            const map = match_obj.data.map;
            if ((!strings.endsWithCharOrIsZeroLength(query, "*"))) {
                var slices = map.list.slice();
                _ = &slices;
                const keys = slices.items(.key);
                const values = slices.items(.value);
                var i: usize = 0;
                _ = &i;
                for (cp_iter_slice(keys)) |key| {
                    _ = &key;
                    if (r.resolveTargetReverse(query, key, values[@as(usize, @intCast(i))], .exact)) |result| {
                        _ = &result;
                        return result;
                    }
                }
            }
            for (cp_iter_slice(map.expansion_keys)) |expansion| {
                _ = &expansion;
                if (strings.endsWithCharOrIsZeroLength(expansion.key, 42)) {
                    if (r.resolveTargetReverse(query, expansion.key, (if (@typeInfo(@TypeOf(expansion)) == .@"enum") @intFromEnum(expansion) else expansion.value), .pattern)) |result| {
