                }
            }
},
}
},
.map => |map| {
const slice = map.list.slice();
            const keys = slice.items(.key);
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(keys)) |map_key| {
                _ = &map_key;
                if (r.conditions.contains(map_key)) {
                    if (r.resolveTargetReverse(query, key, slice.items(.value)[@as(usize, @intCast(i))], kind)) |result| {
                        _ = &result;
                        if (strings.eqlComptime(map_key, "import")) {
                            r.module_type.* = .esm;
                        } else {
                            if (strings.eqlComptime(map_key, "require")) {
                                r.module_type.* = .cjs;
                            }
                        }
