                    }
                }
            }
},
.array => |array| {
for (cp_iter_slice(array)) |target_value| {
                _ = &target_value;
                if (r.resolveTargetReverse(query, key, target_value, kind)) |result| {
                    _ = &result;
                    return result;
                }
            }
},
else => {

},
}
            return null;
    }
