pub fn findInvalidSegment(path_: []const u8) ?[]const u8 {
        const slash = ((strings.indexAnyComptime(path_, "/\\")) orelse { return ""; });
        var path = path_[(slash + 1)..];
        _ = &path;
        while ((path.len > 0)) {
            var segment = path;
            _ = &segment;
            if (strings.indexAnyComptime(path, "/\\")) |new_slash| {
                _ = &new_slash;
                segment = path[0..new_slash];
                path = path[(new_slash + 1)..];
            } else {
                path = "";
            }
            switch (segment.len) {
1 => {
if (strings.eqlComptimeIgnoreLen(segment, ".")) {
                return segment;
            }
},
2 => {
if (strings.eqlComptimeIgnoreLen(segment, "..")) {
                return segment;
            }
},
12 => {
if (strings.eqlComptimeIgnoreLen(segment, "node_modules")) {
                return segment;
            }
},
else => {

},
}
        }
        return null;
}
